mapper.update:
update class set name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId},
subject = #{subject},
create_time = #{createTime}, update_time = #{updateTime} where id = #{id}

mapper.select:
select id,name,room,begin_date,end_date,master_id,create_time,update_time, case when begin_date < localtimestamp and localtimestamp < end_date then '已开班' when begin_date > localtimestamp then '未开班' when localtimestamp > end_date then '已结课' end status from class
name = #{name}
and end_date between #{beginTime} and #{endTime}
